sp_widget.client_script:
api.controller = function($window) {
  var c = this;

  c.openArticle = function(article) {
    $window.location.href = '/kb?id=kb_article&sys_id=' + article.sys_id;
  };
};

sp_widget.css:
/*
===============================================================================
KB FEATURED ARTICLES — SPAR Futuristic edition
Paste into the widget's CSS field
Moves the dark-grey/forest-green look to the theme's light glass-card language:
white/glass cards, red-to-green gradient accents, bold hover glow.
===============================================================================
*/

/* Container */
.kb-featured {
  padding: 24px !important;
  font-family: 'Inter', 'Segoe UI', sans-serif !important;
}

/* Header */
.kb-header {
  margin-bottom: 24px !important;
}
.kb-title {
  font-size: 1.5rem !important;
  font-weight: 800 !important;
  color: #0F172A !important;
  letter-spacing: -0.02em !important;
  margin-bottom: 4px !important;
  font-family: 'Inter', 'Segoe UI', sans-serif !important;
}
.kb-subtitle {
  font-size: 0.875rem !important;
  color: #64748B !important;
}

/* Grid */
.kb-grid {
  display: grid !important;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)) !important;
  gap: 16px !important;
}

/* Card — light glass, gradient top edge revealed on hover, bold lift + glow */
.kb-card {
  position: relative !important;
  background: rgba(255, 255, 255, 0.9) !important;
  border: 1px solid #E2E8F0 !important;
  border-radius: 12px !important;
  padding: 20px !important;
  cursor: pointer !important;
  overflow: hidden !important;
  transition: transform 280ms cubic-bezier(0.34, 1.56, 0.64, 1),
              box-shadow 280ms ease,
              border-color 280ms ease !important;
  display: flex !important;
  flex-direction: column !important;
  gap: 8px !important;
  animation: kbFadeInUp 450ms cubic-bezier(0.16,1,0.3,1) both !important;
}
.kb-card::before {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  height: 3px !important;
  background: linear-gradient(90deg, $brand-primary 0%, $brand-success 100%) !important;
  opacity: 0 !important;
  transition: opacity 280ms ease !important;
}
.kb-card:hover {
  background: #ffffff !important;
  border-color: rgba(227, 6, 19, 0.25) !important;
  transform: translateY(-6px) !important;
  box-shadow: 0 14px 28px -6px rgba(227, 6, 19, 0.18) !important;
}
.kb-card:hover::before {
  opacity: 1 !important;
}

/* Stagger the entrance so the grid cascades in */
.kb-grid .kb-card:nth-child(2) { animation-delay: 60ms !important; }
.kb-grid .kb-card:nth-child(3) { animation-delay: 120ms !important; }
.kb-grid .kb-card:nth-child(4) { animation-delay: 180ms !important; }
.kb-grid .kb-card:nth-child(5) { animation-delay: 240ms !important; }
.kb-grid .kb-card:nth-child(6) { animation-delay: 300ms !important; }

/* Category badge — gradient chip, glows a little brighter on card hover */
.kb-card-category {
  display: inline-block !important;
  background: linear-gradient(135deg, rgba(0, 122, 51, 0.12) 0%, rgba(227, 6, 19, 0.10) 100%) !important;
  color: $brand-success !important;
  border: 1px solid rgba(0, 122, 51, 0.30) !important;
  border-radius: 999px !important;
  font-size: 0.7rem !important;
  font-weight: 700 !important;
  letter-spacing: 0.05em !important;
  text-transform: uppercase !important;
  padding: 3px 10px !important;
  width: fit-content !important;
  transition: border-color 220ms ease, box-shadow 220ms ease !important;
}
.kb-card:hover .kb-card-category {
  border-color: rgba(227, 6, 19, 0.45) !important;
  box-shadow: 0 0 0 3px rgba(227, 6, 19, 0.08) !important;
}

/* Title */
.kb-card-title {
  font-size: 0.95rem !important;
  font-weight: 700 !important;
  color: #0F172A !important;
  line-height: 1.4 !important;
  margin: 0 !important;
  transition: color 220ms ease !important;
}
.kb-card:hover .kb-card-title {
  color: $brand-primary !important;
}

/* Description */
.kb-card-desc {
  font-size: 0.825rem !important;
  color: #64748B !important;
  line-height: 1.6 !important;
  flex: 1 !important;
  margin: 0 !important;
}

/* Read more — bold green, sweeps to red with an animated arrow on hover */
.kb-read-more {
  display: inline-flex !important;
  align-items: center !important;
  gap: 4px !important;
  font-size: 0.8rem !important;
  font-weight: 700 !important;
  color: $brand-success !important;
  margin-top: auto !important;
  transition: color 220ms ease, letter-spacing 220ms ease !important;
}
.kb-read-more::after {
  content: "\2192" !important; /* → */
  display: inline-block !important;
  transition: transform 220ms cubic-bezier(0.34,1.56,0.64,1) !important;
}
.kb-card:hover .kb-read-more {
  color: $brand-primary !important;
  letter-spacing: 0.03em !important;
}
.kb-card:hover .kb-read-more::after {
  transform: translateX(4px) !important;
}

/* Empty state */
.kb-empty {
  text-align: center !important;
  padding: 48px !important;
  color: #94A3B8 !important;
  font-size: 0.875rem !important;
}

/* Entrance animation */
@keyframes kbFadeInUp {
  from { opacity: 0; transform: translateY(14px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

/* Responsive */
@media (max-width: 768px) {
  .kb-grid {
    grid-template-columns: 1fr !important;
  }
}

sp_widget.script:
(function() {
    var articles = [];

    // Get IT Onboarding KB sys_id
    var kbGr = new GlideRecord('kb_knowledge_base');
    kbGr.addQuery('title', 'IT Onboarding KB');
    kbGr.query();

    if (kbGr.next()) {
        var kbSysId = kbGr.getUniqueValue();

        var gr = new GlideRecord('kb_knowledge');
        gr.addQuery('kb_knowledge_base', kbSysId);
        gr.addQuery('workflow_state', 'published');
        gr.orderByDesc('sys_updated_on');
        gr.setLimit(8);
        gr.query();

        while (gr.next()) {
            articles.push({
                sys_id: gr.getUniqueValue(),
                title: gr.getValue('short_description'),
                short_description: gr.getValue('text') ?
                    gr.getValue('text').replace(/<[^>]*>/g, '').substring(0, 120) + '...' :
                    'Click to read this article',
                category: gr.getDisplayValue('kb_category') || 'General',
                number: gr.getValue('number')
            });
        }
    }

    data.articles = articles;
    data.portalSuffix = 'onboarding';
})();
